        check_reg(regs, 10, x"00000004", "x10", errors);
        check_reg(regs, 11, x"00000001", "x11", errors);
        check_reg(regs, 12, x"00000018", "x12", errors);
        check_reg(regs, 13, x"00000006", "x13", errors);
        check_reg(regs, 29, x"00000000", "x29", errors);

        finish_test("tb_jal_jalr", errors);
        wait;
    end process;
end architecture sim;
